import re

def translate_file(source_file, target_file, lang, translations):
    with open(source_file, 'r', encoding='utf-8') as f:
        content = f.read()

    # Replace language attributes
    content = re.sub(r'<html lang="ru">', f'<html lang="{lang}">', content)
    
    # Update language switcher active state
    content = re.sub(r'<button class="lang-btn active" data-lang="ru" aria-label="Переключить на русский язык" aria-pressed="true">RU</button>',
                     r'<button class="lang-btn" data-lang="ru" aria-label="Переключить на русский язык" aria-pressed="false">RU</button>', content)
    
    if lang == 'en':
        content = re.sub(r'<button class="lang-btn" data-lang="en" aria-label="Switch to English" aria-pressed="false">EN</button>',
                         r'<button class="lang-btn active" data-lang="en" aria-label="Switch to English" aria-pressed="true">EN</button>', content)
        content = re.sub(r'var ARTICLE_ID = \'article_3year_rule_ru\';', 'var ARTICLE_ID = \'article_3year_rule_en\';', content)
        content = re.sub(r'article_3year_rule_ru_', 'article_3year_rule_en_', content)
    elif lang == 'es':
        content = re.sub(r'<button class="lang-btn" data-lang="es" aria-label="Cambiar a español" aria-pressed="false">ES</button>',
                         r'<button class="lang-btn active" data-lang="es" aria-label="Cambiar a español" aria-pressed="true">ES</button>', content)
        content = re.sub(r'var ARTICLE_ID = \'article_3year_rule_ru\';', 'var ARTICLE_ID = \'article_3year_rule_es\';', content)
        content = re.sub(r'article_3year_rule_ru_', 'article_3year_rule_es_', content)

    # Apply translations
    for ru_text in sorted(translations.keys(), key=len, reverse=True):
        target_text = translations[ru_text]
        content = content.replace(ru_text, target_text)

    with open(target_file, 'w', encoding='utf-8') as f:
        f.write(content)

